\addplot[green!60!black, thick, domain=-2:2] {sqrt(9*x^2 + 4)};
\addplot[green!60!black, thick, dashed, domain=-2:2] {-sqrt(9*x^2 + 4)};
\addlegendentry{$z = \pm 2$}
\end{axis}
